pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(c.owner()));
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
